    #[tokio::test]
    async fn context_replays_typed_child_workflow_failure_as_workflow_failed() {
        // A parent replaying a child that failed with a typed `WorkflowFailure`
        // observes `HarvestError::WorkflowFailed` carrying the child's
        // error_type / details / non_retryable — not a stringly-typed
        // `ActivityFailed` (issue #767).
        let child_id = ExecutionId::new();
        let decoded = crate::failure::DecodedWorkflowFailure {
            message: "card declined".into(),
            error_type: Some("ValidationRejected".into()),
            details: Some(serde_json::json!({ "code": 402 })),
            non_retryable: Some(true),
        };
        let events = vec![
            WorkflowEvent::WorkflowStarted {
                input: Value::Null,
                timestamp: Utc::now(),
                last_completion_result: None,
                last_error: None,
                scheduled_time: None,
            },
            WorkflowEvent::ChildWorkflowStarted {
                child_id,
                workflow_name: "charge_card".into(),
                input: Value::Null,
            },
            WorkflowEvent::child_workflow_failed_typed(child_id, &decoded),
        ];

        let ctx = WorkflowContext::for_replay(ExecutionId::new(), events);
        let err = ctx
            .spawn_child_workflow_raw("charge_card", Value::Null)
            .await
            .expect_err("child failure should surface as an Err");

        assert!(
            matches!(err, HarvestError::WorkflowFailed { .. }),
            "expected WorkflowFailed, got {err:?}"
        );
        assert_eq!(err.workflow_error_type(), Some("ValidationRejected"));
        assert_eq!(
            err.workflow_details(),
            Some(&serde_json::json!({ "code": 402 }))
        );
        assert!(err.is_workflow_non_retryable());
    }

    #[tokio::test]
    async fn context_replays_legacy_child_workflow_failure_untyped() {
        // A pre-#767 (untyped) child failure surfaces as `WorkflowFailed` with a
        // `None` error_type — proving the `"Error"` sentinel is converted back to
        // untyped rather than leaking a synthetic class.
        let child_id = ExecutionId::new();
        let events = vec![
            WorkflowEvent::WorkflowStarted {
                input: Value::Null,
                timestamp: Utc::now(),
                last_completion_result: None,
                last_error: None,
                scheduled_time: None,
            },
            WorkflowEvent::ChildWorkflowStarted {
                child_id,
                workflow_name: "charge_card".into(),
                input: Value::Null,
            },
            WorkflowEvent::child_workflow_failed(child_id, "boom"),
        ];

        let ctx = WorkflowContext::for_replay(ExecutionId::new(), events);
        let err = ctx
            .spawn_child_workflow_raw("charge_card", Value::Null)
            .await
            .expect_err("child failure should surface as an Err");

        assert!(!err.is_workflow_non_retryable());
        // A legacy untyped child must produce `non_retryable: None` (not
        // `Some(false)`) so it is byte-identical to a direct untyped failure.
        match err {
            HarvestError::WorkflowFailed {
                error_type,
                details,
                non_retryable,
                ..
            } => {
                assert_eq!(error_type, None);
                assert!(details.is_none());
                assert_eq!(non_retryable, None);
            }
            other => panic!("expected WorkflowFailed, got {other:?}"),
        }
    }

    #[tokio::test]
    async fn context_replays_typed_non_retryable_child_preserves_flag() {
        // A typed non-retryable child failure surfaces `non_retryable == Some(true)`
        // on the underlying field — even for the degenerate `"Error"` class, whose
        // `error_type` still collapses to `None` (issue #767).
        let child_id = ExecutionId::new();
        let decoded = crate::failure::DecodedWorkflowFailure {
            message: "permanent".into(),
            // `"Error"` class collapses to None on decode, but the
            // non-retryable flag keeps the failure "typed".
            error_type: None,
            details: None,
            non_retryable: Some(true),
        };
        let events = vec![
            WorkflowEvent::WorkflowStarted {
                input: Value::Null,
                timestamp: Utc::now(),
                last_completion_result: None,
                last_error: None,
                scheduled_time: None,
            },
            WorkflowEvent::ChildWorkflowStarted {
                child_id,
                workflow_name: "charge_card".into(),
                input: Value::Null,
            },
            WorkflowEvent::child_workflow_failed_typed(child_id, &decoded),
        ];

        let ctx = WorkflowContext::for_replay(ExecutionId::new(), events);
        let err = ctx
            .spawn_child_workflow_raw("charge_card", Value::Null)
            .await
            .expect_err("child failure should surface as an Err");

        assert!(err.is_workflow_non_retryable());
        match err {
            HarvestError::WorkflowFailed {
                error_type,
                non_retryable,
                ..
            } => {
                assert_eq!(error_type, None);
                assert_eq!(non_retryable, Some(true));
            }
            other => panic!("expected WorkflowFailed, got {other:?}"),
        }
    }

    #[tokio::test]
    async fn context_live_child_command_round_trip() {
        let ctx = Arc::new(WorkflowContext::new_test());
        let ctx_for_task = Arc::clone(&ctx);
        let workflow_name = "process_order";

        let join = tokio::spawn(async move {
            ctx_for_task
                .spawn_child_workflow_raw(workflow_name, serde_json::json!({"sku":"book"}))
                .await
        });
        tokio::task::yield_now().await;

        let mut commands = ctx.drain_commands();
        assert_eq!(commands.len(), 1);
        let WorkflowCommand::StartChildWorkflow {
            workflow_name: emitted_name,
            result_tx,
            ..
        } = commands.remove(0)
        else {
            panic!("expected StartChildWorkflow command");
        };
        assert_eq!(emitted_name, workflow_name);
        result_tx
            .send(Ok(serde_json::json!({"ok": true})))
            .expect("receiver should exist");

        let result = join.await.expect("join should succeed");
        assert_eq!(
            result.expect("child call should succeed"),
            serde_json::json!({"ok": true})
        );
    }

    /// When a child's `ChildWorkflowStarted` event is in history but its terminal
    /// hasn't arrived yet, the context must re-emit a `StartChildWorkflow` command
    /// carrying the **existing** `child_id` (not a fresh one) so the worker can
    /// re-park the parent idempotently.
    #[tokio::test]
    async fn context_child_in_progress_re_emits_with_existing_child_id() {
        let child_id = ExecutionId::new();
        let events = vec![
            WorkflowEvent::WorkflowStarted {
                input: Value::Null,
                timestamp: Utc::now(),
                last_completion_result: None,
                last_error: None,
                scheduled_time: None,
            },
            WorkflowEvent::ChildWorkflowStarted {
                child_id,
                workflow_name: "process_order".into(),
                input: serde_json::json!({"sku": "book"}),
            },
        ];

        let ctx = Arc::new(WorkflowContext::for_replay(ExecutionId::new(), events));
        let ctx_task = Arc::clone(&ctx);
        let join = tokio::spawn(async move {
            ctx_task
                .spawn_child_workflow_raw("process_order", serde_json::json!({"sku":"book"}))
                .await
        });
        tokio::task::yield_now().await;

        let mut commands = ctx.drain_commands();
        assert_eq!(
            commands.len(),
            1,
            "in-progress child must re-emit exactly one StartChildWorkflow command"
        );
        let WorkflowCommand::StartChildWorkflow {
            child_id: reused_id,
            workflow_name,
            result_tx,
            ..
        } = commands.remove(0)
        else {
            panic!("expected StartChildWorkflow command");
        };
        assert_eq!(workflow_name, "process_order");
        assert_eq!(
            reused_id, child_id,
            "re-emitted command must carry the existing child_id, not a new one"
        );

        result_tx
            .send(Ok(serde_json::json!({"done": true})))
            .expect("receiver must be alive");
        let result = join.await.expect("join").expect("should succeed");
        assert_eq!(result, serde_json::json!({"done": true}));
    }

