        tokio::pin!(fut);
        tokio::select! {
            _ = &mut fut => panic!("complete() should suspend, not complete"),
            () = tokio::time::sleep(std::time::Duration::from_millis(20)) => {}
        }

        let commands = ctx.drain_commands();
